    BaseSubjectContractRegistry contracts,
    IBasePolicyOrchestrator policy,
    BaseOpaqueTokenProtector tokens,
    TimeProvider timeProvider,
    BaseSubjectRetirementOperationalState operationalState,
    BaseSubjectRetirementControlDispatcher retirementControls) : IBaseSubjectRetirementRuntime, IAsyncDisposable, IDisposable
{
    private const string FixedAcknowledgementGrant = "base.subjectRetirement.acknowledge";
    private readonly BaseSubjectRetirementEvidenceCodec _codec = new(tokens, timeProvider);
    private readonly BaseSubjectLifecycleTokenCodec _lifecycleCodec = new(tokens, timeProvider);
    private readonly BaseSubjectScopeProtector _scopes = new(tokens);
    private readonly SemaphoreSlim _providerSlots = new(64, 64);
    private static readonly TimeSpan ShutdownDrainTimeout = TimeSpan.FromSeconds(30);

    public async ValueTask<bool> AuthorizeGenerationAsync(BaseSession session, BaseInstalledSubjectRetirementConsumer installed, CancellationToken cancellationToken)
        => (await AuthorizeAcknowledgementAsync(session, installed, cancellationToken).ConfigureAwait(false)) is not null;

    private async ValueTask<byte[]?> AuthorizeAcknowledgementAsync(BaseSession session, BaseInstalledSubjectRetirementConsumer installed, CancellationToken cancellationToken)
    {
        if (!AudienceAllows(installed.Definition.Audience, session.Principal)) return null;
        BaseGeneratedSubjectRegistration? contract = contracts.Find(installed.Lifecycle.Definition.ContractId, installed.Lifecycle.Definition.ContractVersion);
        if (contract is null) return null;
        OperationContext operation = session.Operation(BaseOperationKind.SubjectRetirementAcknowledge, installed.Definition.ConsumerId);
        BaseOwnedSubjectScopeEvidence scope = Scope(session, installed); if (scope.Kind != BaseSubjectScopeKind.Global && string.IsNullOrEmpty(scope.Value)) return null;
        var resource = new CollectionDefinition { Id = installed.Definition.ConsumerId, Name = installed.Definition.ConsumerId, Kind = BaseCollectionKinds.Custom, SchemaMode = SchemaMode.Strict, UnknownFields = UnknownFieldPolicy.Reject, System = true, SystemOwnerModuleId = installed.Definition.OwningModuleId };
        OperationResult<BasePolicyEvaluation> authorization = await policy.EvaluateWriteAsync(new() { Principal = session.Principal, Operation = operation, Collection = resource, ResourceKind = PolicyResourceKind.SubjectLifecycle }, cancellationToken).ConfigureAwait(false);
        if (!BaseSystemCollectionGate.HasExactSubjectLifecycleGrant(authorization, installed.Definition.AcknowledgementGrantId, installed.Definition.OwningModuleId, installed.Definition.ConsumerId, contract.Definition.Id, contract.Definition.Version, session.Principal, operation) || authorization.Value?.Authority is null) return null;
        OperationContext fixedOperation = session.Operation(BaseOperationKind.SubjectRetirementAcknowledge, FixedAcknowledgementGrant);
        OperationResult<BasePolicyEvaluation> fixedAuthorization = await policy.EvaluateWriteAsync(new() { Principal = session.Principal, Operation = fixedOperation, Collection = resource, ResourceKind = PolicyResourceKind.SubjectLifecycle }, cancellationToken).ConfigureAwait(false);
        if (!BaseSystemCollectionGate.HasExactSubjectLifecycleGrant(fixedAuthorization, FixedAcknowledgementGrant, installed.Definition.OwningModuleId, FixedAcknowledgementGrant, contract.Definition.Id, contract.Definition.Version, session.Principal, fixedOperation) || fixedAuthorization.Value?.Authority is null) return null;
        byte[] first = authorization.Value.Authority.Checksum.ToArray(); byte[] second = fixedAuthorization.Value.Authority.Checksum.ToArray(); byte[] combined = new byte[first.Length + second.Length]; first.CopyTo(combined, 0); second.CopyTo(combined, first.Length); return SHA256.HashData(combined);
    }

    public async ValueTask<BaseResult<BaseSubjectAdvisoryLifecycleDelivery<TSubject>>> IssueAdvisoryAsync<TSubject>(BaseSession session, BaseInstalledSubjectRetirementConsumer installed, BaseSubjectLifecycleDelivery<TSubject> delivery, CancellationToken cancellationToken)
    {
        if (installed.Definition.Participation != BaseSubjectRetirementParticipation.AdvisoryAcknowledgement) return Failure<BaseSubjectAdvisoryLifecycleDelivery<TSubject>>(OperationStatus.ValidationFailed, BaseSubjectRetirementErrorCodes.ContractInvalid, ErrorCategory.Validation);
        byte[]? grantDigest = await AuthorizeAcknowledgementAsync(session, installed, cancellationToken).ConfigureAwait(false); if (grantDigest is null) return Failure<BaseSubjectAdvisoryLifecycleDelivery<TSubject>>(OperationStatus.PolicyDenied, BaseSubjectRetirementErrorCodes.Unauthorized, ErrorCategory.Authorization);
        BaseSubjectLifecycleFact fact = delivery.Fact.Fact; BaseOwnedSubjectScopeEvidence scope = Scope(session, installed); BaseGeneratedSubjectRegistration? contract = contracts.Find(fact.ContractId, fact.ContractVersion); if (contract is null || !TryDeliveryAuthority(session, installed, delivery, contract, scope, out BaseSubjectLifecycleTokenPayload? authority) || authority is null) return Failure<BaseSubjectAdvisoryLifecycleDelivery<TSubject>>(OperationStatus.ValidationFailed, BaseSubjectRetirementErrorCodes.ContractInvalid, ErrorCategory.Validation);
        DateTimeOffset issued = timeProvider.GetUtcNow(); DateTimeOffset expires = checked(issued + installed.Lifecycle.Definition.Limits.MaximumCheckpointLag);
        var payload = Payload(installed, fact, null, issued, expires, grantDigest, contract.Checksum, authority); byte[] token = _codec.Protect(payload, BaseSubjectRetirementEvidenceCodec.Binding(session.ApplicationId, installed, scope)); BaseMutationRequestIdentity identity = Identity(installed, token);
        return new BaseSuccess<BaseSubjectAdvisoryLifecycleDelivery<TSubject>>(new() { Lifecycle = delivery, Acknowledgement = new(token), AcknowledgementIdentity = identity }, OperationStatus.Ok, null, null, null, null);
    }

    public async ValueTask<BaseResult<BaseSubjectRequiredLifecycleDelivery<TSubject>>> IssueRequiredAsync<TSubject>(BaseSession session, BaseInstalledSubjectRetirementConsumer installed, BaseSubjectLifecycleDelivery<TSubject> delivery, CancellationToken cancellationToken)
    {
        if (installed.Definition.Participation != BaseSubjectRetirementParticipation.RequiredBeforePurge) return Failure<BaseSubjectRequiredLifecycleDelivery<TSubject>>(OperationStatus.ValidationFailed, BaseSubjectRetirementErrorCodes.ContractInvalid, ErrorCategory.Validation);
        byte[]? grantDigest = await AuthorizeAcknowledgementAsync(session, installed, cancellationToken).ConfigureAwait(false); if (grantDigest is null) return Failure<BaseSubjectRequiredLifecycleDelivery<TSubject>>(OperationStatus.PolicyDenied, BaseSubjectRetirementErrorCodes.Unauthorized, ErrorCategory.Authorization);
        BaseSubjectLifecycleFact fact = delivery.Fact.Fact; if (fact.Transitioned?.CurrentState != BaseSubjectLifecycleState.Tombstoned) return Failure<BaseSubjectRequiredLifecycleDelivery<TSubject>>(OperationStatus.ValidationFailed, BaseSubjectRetirementErrorCodes.ContractInvalid, ErrorCategory.Validation);
        BaseGeneratedSubjectRegistration? contract = contracts.Find(fact.ContractId, fact.ContractVersion); if (contract is null || stores.GetStoreForCollection(contract.Definition.ValidationPlan.PrivateCollectionId) is not IBaseSubjectRetirementStore store) return Failure<BaseSubjectRequiredLifecycleDelivery<TSubject>>(OperationStatus.CapabilityUnavailable, BaseSubjectRetirementErrorCodes.ProviderContractInvalid, ErrorCategory.Capability);
        BaseOwnedSubjectScopeEvidence scope = Scope(session, installed); if (!TryDeliveryAuthority(session, installed, delivery, contract, scope, out BaseSubjectLifecycleTokenPayload? authority) || authority is null) return Failure<BaseSubjectRequiredLifecycleDelivery<TSubject>>(OperationStatus.ValidationFailed, BaseSubjectRetirementErrorCodes.ContractInvalid, ErrorCategory.Validation);
        var inspectionRequest = new BaseSubjectRetirementInspectionRequest { ContractId = fact.ContractId, ContractVersion = fact.ContractVersion, SubjectId = fact.SubjectId, AuthorityEpoch = fact.AuthorityEpoch, Incarnation = fact.Incarnation, ScopeAuthority = new() { Mode = BaseSubjectScopeQueryMode.ExactScope, ExactScope = scope, InstalledAuthorityDigest = contract.Checksum }, IncludeTerminalSummary = false, MaximumResultBytes = installed.Definition.Limits.MaximumReceiptBytes, DeadlineUtc = timeProvider.GetUtcNow() + installed.Definition.Limits.AcknowledgementTimeout };
        OperationResult<BaseSubjectRetirementInspection> read; try { read = await InvokeProviderAsync(token => store.InspectAsync(inspectionRequest, token), installed.Definition.Limits.AcknowledgementTimeout, cancellationToken).ConfigureAwait(false); } catch (TimeoutException) { return Failure<BaseSubjectRequiredLifecycleDelivery<TSubject>>(OperationStatus.StoreError, BaseSubjectRetirementErrorCodes.Timeout, ErrorCategory.Store); }
        if (!read.IsSuccess() || read.Value?.CurrentBarrier is not { } barrier) return Failure<BaseSubjectRequiredLifecycleDelivery<TSubject>>(read.Status, read.Error?.Code ?? BaseSubjectRetirementErrorCodes.ProviderContractInvalid, read.Error?.Category ?? ErrorCategory.Store);
        if (!ValidateInspection(read.Value, inspectionRequest, scope)) return Failure<BaseSubjectRequiredLifecycleDelivery<TSubject>>(OperationStatus.CapabilityUnavailable, BaseSubjectRetirementErrorCodes.ProviderContractInvalid, ErrorCategory.Capability);
        if (barrier.TombstoneSequence != fact.SubjectSequence) return Failure<BaseSubjectRequiredLifecycleDelivery<TSubject>>(OperationStatus.Conflict, BaseSubjectRetirementErrorCodes.BarrierPending, ErrorCategory.Conflict);
        DateTimeOffset issued = timeProvider.GetUtcNow();
        DateTimeOffset expires = RequiredEvidenceExpiry(issued, installed.Lifecycle.Definition.Limits.MaximumCheckpointLag, barrier.DeadlineUtc);
        var expectation = new BaseSubjectRequiredBarrierExpectation { Generation = barrier.Generation, Checksum = barrier.BarrierChecksum };
        var payload = Payload(installed, fact, expectation, issued, expires, grantDigest, contract.Checksum, authority); byte[] token = _codec.Protect(payload, BaseSubjectRetirementEvidenceCodec.Binding(session.ApplicationId, installed, scope)); BaseMutationRequestIdentity identity = Identity(installed, token);
        return new BaseSuccess<BaseSubjectRequiredLifecycleDelivery<TSubject>>(new() { Lifecycle = delivery, Acknowledgement = new(token), AcknowledgementIdentity = identity }, OperationStatus.Ok, null, null, null, null);
    }

    public async ValueTask<BaseResult<BaseSubjectAcknowledgementResult>> AcknowledgeAsync(BaseSession session, BaseInstalledSubjectRetirementConsumer installed, ReadOnlyMemory<byte> evidence, BaseSubjectRetirementParticipation participation, BaseSubjectAcknowledgementDisposition disposition, BaseMutationRequestIdentity identity, BaseActivationGuard? activationGuard, CancellationToken cancellationToken)
    {
        if (installed.Definition.Participation != participation || !Enum.IsDefined(disposition) || !AudienceAllows(installed.Definition.Audience, session.Principal)) return Failure<BaseSubjectAcknowledgementResult>(OperationStatus.PolicyDenied, BaseSubjectRetirementErrorCodes.Unauthorized, ErrorCategory.Authorization);
        BaseGeneratedSubjectRegistration? contract = contracts.Find(installed.Lifecycle.Definition.ContractId, installed.Lifecycle.Definition.ContractVersion); if (contract is null) return Failure<BaseSubjectAcknowledgementResult>(OperationStatus.CapabilityUnavailable, BaseSubjectRetirementErrorCodes.ProviderContractInvalid, ErrorCategory.Capability);
        BaseOwnedSubjectScopeEvidence scope = Scope(session, installed); byte[] binding = BaseSubjectRetirementEvidenceCodec.Binding(session.ApplicationId, installed, scope);
        if (!_codec.TryRead(evidence.Span, participation, binding, contract.Definition.SubjectIdKind, out BaseSubjectRetirementEvidencePayload? payload) || payload is null || payload.ConsumerId != installed.Definition.ConsumerId || payload.ConsumerVersion != installed.Definition.ConsumerVersion || payload.ConsumerChecksum != installed.Checksum || payload.ContractChecksum != contract.Checksum || (payload.AllowedDispositions & (1 << (int)disposition)) == 0 || !IdentityMatches(identity, installed, evidence.Span)) return Failure<BaseSubjectAcknowledgementResult>(OperationStatus.ValidationFailed, BaseSubjectRetirementErrorCodes.ContractInvalid, ErrorCategory.Validation);
        OperationContext operation = session.Operation(BaseOperationKind.SubjectRetirementAcknowledge, installed.Definition.ConsumerId); var resource = new CollectionDefinition { Id = installed.Definition.ConsumerId, Name = installed.Definition.ConsumerId, Kind = BaseCollectionKinds.Custom, SchemaMode = SchemaMode.Strict, UnknownFields = UnknownFieldPolicy.Reject, System = true, SystemOwnerModuleId = installed.Definition.OwningModuleId };
        OperationResult<BasePolicyEvaluation> authorization = await policy.EvaluateWriteAsync(new() { Principal = session.Principal, Operation = operation, Collection = resource, ResourceKind = PolicyResourceKind.SubjectLifecycle }, cancellationToken).ConfigureAwait(false);
        if (!BaseSystemCollectionGate.HasExactSubjectLifecycleGrant(authorization, installed.Definition.AcknowledgementGrantId, installed.Definition.OwningModuleId, installed.Definition.ConsumerId, payload.ContractId, payload.ContractVersion, session.Principal, operation)) return Failure<BaseSubjectAcknowledgementResult>(OperationStatus.PolicyDenied, BaseSubjectRetirementErrorCodes.Unauthorized, ErrorCategory.Authorization);
        OperationContext fixedOperation = session.Operation(BaseOperationKind.SubjectRetirementAcknowledge, FixedAcknowledgementGrant); OperationResult<BasePolicyEvaluation> fixedAuthorization = await policy.EvaluateWriteAsync(new() { Principal = session.Principal, Operation = fixedOperation, Collection = resource, ResourceKind = PolicyResourceKind.SubjectLifecycle }, cancellationToken).ConfigureAwait(false);
        if (!BaseSystemCollectionGate.HasExactSubjectLifecycleGrant(fixedAuthorization, FixedAcknowledgementGrant, installed.Definition.OwningModuleId, FixedAcknowledgementGrant, payload.ContractId, payload.ContractVersion, session.Principal, fixedOperation) || authorization.Value?.Authority is null || fixedAuthorization.Value?.Authority is null) return Failure<BaseSubjectAcknowledgementResult>(OperationStatus.PolicyDenied, BaseSubjectRetirementErrorCodes.Unauthorized, ErrorCategory.Authorization); byte[] currentGrantDigest = CombinedAuthorityDigest(authorization.Value.Authority, fixedAuthorization.Value.Authority); if (!CryptographicOperations.FixedTimeEquals(currentGrantDigest, payload.GrantAuthorityDigest)) return Failure<BaseSubjectAcknowledgementResult>(OperationStatus.PolicyDenied, BaseSubjectRetirementErrorCodes.Unauthorized, ErrorCategory.Authorization);
        IRecordStore? rawStore = stores.GetStoreForCollection(contract.Definition.ValidationPlan.PrivateCollectionId); if (rawStore is not IBaseSubjectRetirementStore store || rawStore is not IBaseSubjectLifecycleStore lifecycleStore) return Failure<BaseSubjectAcknowledgementResult>(OperationStatus.CapabilityUnavailable, BaseSubjectRetirementErrorCodes.ProviderContractInvalid, ErrorCategory.Capability);
        OperationResult<BaseSubjectLifecycleProviderInspection> lifecycleAuthority; try { lifecycleAuthority = await InvokeProviderAsync(token => lifecycleStore.InspectAsync(new() { ContractId = payload.ContractId, ContractVersion = payload.ContractVersion, ConsumerId = payload.ConsumerId, ScopeAuthority = new() { Mode = BaseSubjectScopeQueryMode.ExactScope, ExactScope = scope, InstalledAuthorityDigest = installed.Lifecycle.Checksum }, SubjectId = payload.SubjectId, IncludeTerminalReceipt = false, MaximumResultBytes = 4096, DeadlineUtc = timeProvider.GetUtcNow().Add(installed.Definition.Limits.AcknowledgementTimeout) }, token), installed.Definition.Limits.AcknowledgementTimeout, cancellationToken).ConfigureAwait(false); } catch (TimeoutException) { return Failure<BaseSubjectAcknowledgementResult>(OperationStatus.StoreError, BaseSubjectRetirementErrorCodes.Timeout, ErrorCategory.Store); }
        BaseSubjectLifecycleConsumerInspection? currentConsumer = lifecycleAuthority.Value?.Consumers.SingleOrDefault(value => value.ConsumerId == payload.ConsumerId && value.ConsumerVersion == payload.ConsumerVersion); if (!lifecycleAuthority.IsSuccess() || lifecycleAuthority.Value is null || currentConsumer is null || lifecycleAuthority.Value.StoreInstanceId != payload.StoreInstanceId || lifecycleAuthority.Value.RestoreEpoch != payload.RestoreEpoch || lifecycleAuthority.Value.DeliveryEpoch != payload.DeliveryEpoch || currentConsumer.ProjectionGeneration != payload.ProjectionGeneration || currentConsumer.CheckpointGeneration != payload.CheckpointGeneration) return Failure<BaseSubjectAcknowledgementResult>(OperationStatus.ValidationFailed, BaseSubjectRetirementErrorCodes.ContractInvalid, ErrorCategory.Validation);
        BaseInstalledSubjectRetirementPolicy? retirementPolicy = (session.Services.GetService(typeof(BaseSubjectRetirementRegistry)) as BaseSubjectRetirementRegistry)?.FindPolicy(payload.ContractId, payload.ContractVersion);
        var acknowledgement = new BaseSubjectLifecycleAcknowledgement { ConsumerId = payload.ConsumerId, ConsumerVersion = payload.ConsumerVersion, ConsumerChecksum = installed.Lifecycle.Checksum, ContractId = payload.ContractId, ContractVersion = payload.ContractVersion, SubjectId = payload.SubjectId, AuthorityEpoch = payload.AuthorityEpoch, Incarnation = payload.Incarnation, ThroughSubjectSequence = payload.ThroughSequence, Disposition = disposition, Participation = participation, RequiredBarrier = payload.Barrier, Identity = identity };
        byte[] semanticDigest = SemanticAcknowledgementDigest(evidence.Span, disposition, payload); BaseMutationRequestIdentity executionIdentity = BaseMutationRequestIdentity.Create(identity.Scope, identity.Operation, identity.IdempotencyKey, BaseMutationRequestFingerprint.Create(semanticDigest)); acknowledgement = acknowledgement with { Identity = executionIdentity }; BaseActivationGuard? effectiveGuard = activationGuard is null ? null : activationGuard with { ChildRequestFingerprint = semanticDigest.ToImmutableArray() }; var processor = new BaseSubjectRetirementAcknowledgementProcessor(new() { Acknowledgement = acknowledgement, Scope = scope, RetirementConsumerChecksum = installed.Checksum, RetirementPolicyChecksum = retirementPolicy?.Definition.PolicyChecksum ?? new string('0', 64), ObservedAtUtc = timeProvider.GetUtcNow(), DeadlineUtc = timeProvider.GetUtcNow() + installed.Definition.Limits.AcknowledgementTimeout, ActivationGuard = effectiveGuard });
        RecordMutationExecutionResult execution; try { execution = await InvokeProviderAsync(token => store.ExecuteAsync(processor, new() { AcquisitionTimeout = installed.Definition.Limits.AcknowledgementTimeout, TransactionTimeout = installed.Definition.Limits.AcknowledgementTimeout, CommitCompletionTimeout = installed.Definition.Limits.AcknowledgementTimeout, AtomicRequest = new() { Identity = executionIdentity, StructuralDigest = semanticDigest, ExpiresAt = timeProvider.GetUtcNow().AddDays(30), MaxReceiptBytes = installed.Definition.Limits.MaximumReceiptBytes } }, token), installed.Definition.Limits.AcknowledgementTimeout + installed.Definition.Limits.AcknowledgementTimeout + installed.Definition.Limits.AcknowledgementTimeout, cancellationToken).ConfigureAwait(false); } catch (TimeoutException) { return Failure<BaseSubjectAcknowledgementResult>(OperationStatus.StoreError, BaseSubjectRetirementErrorCodes.CommitIndeterminate, ErrorCategory.Store); }
        if (execution.Outcome == RecordMutationExecutionOutcome.Committed && processor.Result is not null) { await TryDispatchControlsAsync().ConfigureAwait(false); return new BaseSuccess<BaseSubjectAcknowledgementResult>(processor.Result, processor.Result.Outcome == BaseSubjectRetirementMutationOutcome.Duplicate ? OperationStatus.Ok : OperationStatus.Updated, null, null, null, null); }
        BaseError? error = execution.Error ?? execution.Processing?.Error; string code = error?.Code == "base.runtime.request.fingerprintConflict" ? BaseSubjectRetirementErrorCodes.AcknowledgementConflict : error?.Code ?? BaseSubjectRetirementErrorCodes.ProviderContractInvalid; return Failure<BaseSubjectAcknowledgementResult>(execution.Outcome == RecordMutationExecutionOutcome.Indeterminate ? OperationStatus.StoreError : OperationStatus.Conflict, code, error?.Category ?? ErrorCategory.Store);
    }

    public async ValueTask<BaseResult<BaseSubjectRetirementPage>> ReadBarriersAsync(BaseSession session, string contractId, int contractVersion, BaseSubjectRetirementBarrierState? state, BaseSubjectRetirementCursor? after, int take, CancellationToken cancellationToken)
    {
        BaseGeneratedSubjectRegistration? contract = contracts.Find(contractId, contractVersion); if (contract is null) return Failure<BaseSubjectRetirementPage>(OperationStatus.PolicyDenied, BaseSubjectRetirementErrorCodes.Unauthorized, ErrorCategory.Authorization);
        OperationContext operation = session.Operation(BaseOperationKind.SubjectRetirementInspect, "base.subjectRetirement.barriers.query"); if (!await AuthorizedAsync(session, contract, "base.subjectRetirement.barrier.inspect", operation, false, cancellationToken).ConfigureAwait(false)) return Failure<BaseSubjectRetirementPage>(OperationStatus.PolicyDenied, BaseSubjectRetirementErrorCodes.Unauthorized, ErrorCategory.Authorization); bool allScopes = session.Principal.SubjectKind is AccessSubjectKind.Admin or AccessSubjectKind.System; if (allScopes && !await AuthorizedAsync(session, contract, "base.subjectRetirement.scope.all", session.Operation(BaseOperationKind.SubjectRetirementInspect, "base.subjectRetirement.scope.all"), false, cancellationToken).ConfigureAwait(false)) return Failure<BaseSubjectRetirementPage>(OperationStatus.PolicyDenied, BaseSubjectRetirementErrorCodes.Unauthorized, ErrorCategory.Authorization);
        if (take is < 1 or > 256) return Failure<BaseSubjectRetirementPage>(OperationStatus.ValidationFailed, BaseSubjectRetirementErrorCodes.ContractInvalid, ErrorCategory.Validation);
        IRecordStore raw = stores.GetStoreForCollection(contract.Definition.ValidationPlan.PrivateCollectionId) ?? throw new InvalidOperationException(BaseSubjectRetirementErrorCodes.ProviderContractInvalid); if (raw is not IBaseSubjectRetirementStore store || raw is not IBaseSubjectLifecycleStore lifecycleStore) return Failure<BaseSubjectRetirementPage>(OperationStatus.CapabilityUnavailable, BaseSubjectRetirementErrorCodes.ProviderContractInvalid, ErrorCategory.Capability);
        BaseOwnedSubjectScopeEvidence? scope = allScopes ? null : Scope(session, contract, operation); if(scope is not null&&!ValidScope(scope))return Failure<BaseSubjectRetirementPage>(OperationStatus.PolicyDenied,BaseSubjectRetirementErrorCodes.ScopeAuthorityInvalid,ErrorCategory.Authorization); BaseSubjectLifecycleInspectionAuthority? installedInspection = allScopes ? (session.Services.GetService(typeof(BaseSubjectLifecycleInspectionAuthorityRegistry)) as BaseSubjectLifecycleInspectionAuthorityRegistry)?.Find(contractId, contractVersion) : null; if (allScopes && installedInspection is null) return Failure<BaseSubjectRetirementPage>(OperationStatus.CapabilityUnavailable, BaseSubjectRetirementErrorCodes.ProviderContractInvalid, ErrorCategory.Capability); string authorityDigest = installedInspection?.Digest ?? contract.Checksum; var scopeAuthority = new BaseSubjectScopeQueryAuthority { Mode = allScopes ? BaseSubjectScopeQueryMode.AllAuthorizedScopes : BaseSubjectScopeQueryMode.ExactScope, ExactScope = scope, InstalledAuthorityDigest = authorityDigest }; OperationResult<BaseSubjectLifecycleProviderInspection> authority; try { authority = await InvokeProviderAsync(token => lifecycleStore.InspectAsync(new() { ContractId = contractId, ContractVersion = contractVersion, ConsumerId = null, ScopeAuthority = scopeAuthority, SubjectId = null, IncludeTerminalReceipt = false, MaximumResultBytes = 4096, DeadlineUtc = timeProvider.GetUtcNow().AddSeconds(5) }, token), TimeSpan.FromSeconds(5), cancellationToken).ConfigureAwait(false); } catch (TimeoutException) { return Failure<BaseSubjectRetirementPage>(OperationStatus.StoreError, BaseSubjectRetirementErrorCodes.Timeout, ErrorCategory.Store); }
        if (!authority.IsSuccess() || authority.Value is null) return Failure<BaseSubjectRetirementPage>(authority.Status, authority.Error?.Code ?? BaseSubjectRetirementErrorCodes.ProviderContractInvalid, authority.Error?.Category ?? ErrorCategory.Store);
        byte[] binding = CursorBinding(session.ApplicationId, contract, state, scope, authority.Value.StoreInstanceId, authority.Value.RestoreEpoch); BaseSubjectRetirementBarrierKey? providerAfter = null;
        if (after is not null && !TryReadCursor(after, binding, contract.Definition.SubjectIdKind, out providerAfter)) return Failure<BaseSubjectRetirementPage>(OperationStatus.ValidationFailed, BaseSubjectRetirementErrorCodes.CursorInvalid, ErrorCategory.Validation);
        OperationResult<BaseSubjectRetirementBarrierPage> result; try { result = await InvokeProviderAsync(token => store.ReadBarriersAsync(new() { ApplicationId = session.ApplicationId, ContractId = contractId, ContractVersion = contractVersion, ScopeAuthority = scopeAuthority, State = state, After = providerAfter, Take = take, MaximumResultBytes = 1_048_576, DeadlineUtc = timeProvider.GetUtcNow().AddSeconds(30) }, token), TimeSpan.FromSeconds(30), cancellationToken).ConfigureAwait(false); } catch (TimeoutException) { return Failure<BaseSubjectRetirementPage>(OperationStatus.StoreError, BaseSubjectRetirementErrorCodes.Timeout, ErrorCategory.Store); }
        if (!result.IsSuccess() || result.Value is null) return Failure<BaseSubjectRetirementPage>(result.Status, result.Error?.Code ?? BaseSubjectRetirementErrorCodes.ProviderContractInvalid, result.Error?.Category ?? ErrorCategory.Store);
        if (!ValidateBarrierPage(_scopes, result.Value, contract, state, providerAfter, take, scope)) return Failure<BaseSubjectRetirementPage>(OperationStatus.CapabilityUnavailable, BaseSubjectRetirementErrorCodes.ProviderContractInvalid, ErrorCategory.Capability);
        BaseSubjectRetirementCursor? next = result.Value.Next is null ? null : ProtectCursor(result.Value.Next, binding);
        return new BaseSuccess<BaseSubjectRetirementPage>(new() { Barriers = [.. result.Value.Barriers.Select(static row => row.Barrier)], Next = next, CapturedBarrierGeneration = result.Value.CapturedBarrierGeneration }, OperationStatus.Ok, null, null, null, null);
    }

    private BaseSubjectRetirementCursor ProtectCursor(BaseSubjectRetirementBarrierKey key, ReadOnlySpan<byte> binding)
    {
        using var stream = new MemoryStream(); using var writer = new BinaryWriter(stream, Encoding.UTF8, true); writer.Write((byte)key.ScopeKind); writer.Write(key.ScopeIndexDigest); Write(writer, key.ContractId); writer.Write(key.ContractVersion); Write(writer, key.SubjectId.Value); writer.Write(key.AuthorityEpoch.ToArray()); writer.Write(key.Incarnation.ToArray()); writer.Flush();
        return new(Encoding.ASCII.GetBytes(tokens.Protect("hpd.base.subject-retirement.cursor.v1", 1, stream.ToArray(), binding)));
    }
    private bool TryReadCursor(BaseSubjectRetirementCursor cursor, ReadOnlySpan<byte> binding, BaseSubjectIdKind idKind, out BaseSubjectRetirementBarrierKey? key)
    {
        key = null; BaseOpaqueTokenResult value = tokens.Unprotect("hpd.base.subject-retirement.cursor.v1", 1, Encoding.ASCII.GetString(cursor.ToArray()), 65, 2048, binding); if (value.Status != BaseOpaqueTokenStatus.Valid || value.Plaintext is null) return false;
        try { using var stream = new MemoryStream(value.Plaintext, false); using var reader = new BinaryReader(stream, Encoding.UTF8, true); var kind = (BaseSubjectScopeKind)reader.ReadByte(); byte[] digest = reader.ReadBytes(32); string contractId = Read(reader); int version = reader.ReadInt32(); BaseSubjectId subjectId = BaseSubjectId.Create(Read(reader), idKind); var epoch = new BaseSubjectAuthorityEpoch(reader.ReadBytes(16)); var incarnation = new BaseSubjectIncarnation(reader.ReadBytes(24)); if (stream.Position != stream.Length || digest.Length != 32 || !Enum.IsDefined(kind)) return false; key = new() { ScopeKind = kind, ScopeIndexDigest = digest, ContractId = contractId, ContractVersion = version, SubjectId = subjectId, AuthorityEpoch = epoch, Incarnation = incarnation }; return true; } catch { return false; }
    }
    private static byte[] CursorBinding(string applicationId, BaseGeneratedSubjectRegistration contract, BaseSubjectRetirementBarrierState? state, BaseOwnedSubjectScopeEvidence? scope, string storeInstanceId, long restoreEpoch) => SHA256.HashData(Encoding.UTF8.GetBytes($"base.subjectRetirement.cursor.binding.v1\0{applicationId}\0{contract.Definition.Id}\0{contract.Definition.Version}\0{contract.Checksum}\0{(scope is null ? -1 : (int)scope.Kind)}\0{scope?.Value}\0{(state is null ? -1 : (int)state.Value)}\0{storeInstanceId}\0{restoreEpoch}"));
    private static void Write(BinaryWriter writer, string value) { byte[] bytes = Encoding.UTF8.GetBytes(value); writer.Write(bytes.Length); writer.Write(bytes); }
    private static string Read(BinaryReader reader) { int length = reader.ReadInt32(); if (length is < 1 or > 512) throw new FormatException(); byte[] bytes = reader.ReadBytes(length); if (bytes.Length != length) throw new EndOfStreamException(); return Encoding.UTF8.GetString(bytes); }

    public async ValueTask<BaseResult<BaseSubjectRetirementInspection>> InspectAsync(BaseSession session, BaseSubjectRetirementInspectionRequest request, CancellationToken cancellationToken)
    {
        BaseGeneratedSubjectRegistration? contract = contracts.Find(request.ContractId, request.ContractVersion); if (contract is null) return Failure<BaseSubjectRetirementInspection>(OperationStatus.PolicyDenied, BaseSubjectRetirementErrorCodes.Unauthorized, ErrorCategory.Authorization); OperationContext operation = session.Operation(BaseOperationKind.SubjectRetirementInspect, "base.subjectRetirement.barrier.inspect"); if (!await AuthorizedAsync(session, contract, "base.subjectRetirement.barrier.inspect", operation, false, cancellationToken).ConfigureAwait(false)) return Failure<BaseSubjectRetirementInspection>(OperationStatus.PolicyDenied, BaseSubjectRetirementErrorCodes.Unauthorized, ErrorCategory.Authorization); BaseOwnedSubjectScopeEvidence scope = Scope(session, contract, operation); if (!ValidScope(scope)) return Failure<BaseSubjectRetirementInspection>(OperationStatus.PolicyDenied, BaseSubjectRetirementErrorCodes.ScopeAuthorityInvalid, ErrorCategory.Authorization); IRecordStore? raw = stores.GetStoreForCollection(contract.Definition.ValidationPlan.PrivateCollectionId); if (raw is not IBaseSubjectRetirementStore store || raw is not IBaseSubjectLifecycleStore lifecycleStore) return Failure<BaseSubjectRetirementInspection>(OperationStatus.CapabilityUnavailable, BaseSubjectRetirementErrorCodes.ProviderContractInvalid, ErrorCategory.Capability); var scopeAuthority = new BaseSubjectScopeQueryAuthority { Mode = BaseSubjectScopeQueryMode.ExactScope, ExactScope = scope, InstalledAuthorityDigest = contract.Checksum }; OperationResult<BaseSubjectLifecycleProviderInspection> authority; OperationResult<BaseSubjectRetirementInspection> result; try { authority = await InvokeProviderAsync(token => lifecycleStore.InspectAsync(new() { ContractId = request.ContractId, ContractVersion = request.ContractVersion, ConsumerId = null, ScopeAuthority = scopeAuthority, SubjectId = request.SubjectId, IncludeTerminalReceipt = false, MaximumResultBytes = 4096, DeadlineUtc = timeProvider.GetUtcNow().AddSeconds(5) }, token), TimeSpan.FromSeconds(5), cancellationToken).ConfigureAwait(false); if (!authority.IsSuccess() || authority.Value is null) return Failure<BaseSubjectRetirementInspection>(OperationStatus.CapabilityUnavailable, BaseSubjectRetirementErrorCodes.ProviderContractInvalid, ErrorCategory.Capability); result = await InvokeProviderAsync(token => store.InspectAsync(request with { ScopeAuthority = scopeAuthority }, token), TimeSpan.FromSeconds(30), cancellationToken).ConfigureAwait(false); if (!result.IsSuccess() || result.Value is null) return Result(result); if (!ValidateInspection(result.Value, request, scope)) return Failure<BaseSubjectRetirementInspection>(OperationStatus.CapabilityUnavailable, BaseSubjectRetirementErrorCodes.ProviderContractInvalid, ErrorCategory.Capability); } catch (TimeoutException) { return Failure<BaseSubjectRetirementInspection>(OperationStatus.StoreError, BaseSubjectRetirementErrorCodes.Timeout, ErrorCategory.Store); }
        return Result(result);
    }

