    }
    private async ValueTask<T> InvokeProviderAsync<T>(Func<CancellationToken, ValueTask<T>> invoke, TimeSpan timeout, CancellationToken cancellationToken)
    {
        return await InvokeProviderAsync(invoke, timeout, cancellationToken, _providerSlots, operationalState).ConfigureAwait(false);
    }
    internal static async ValueTask<T> InvokeProviderAsync<T>(Func<CancellationToken, ValueTask<T>> invoke, TimeSpan timeout, CancellationToken cancellationToken, SemaphoreSlim slots, BaseSubjectRetirementOperationalState state)
    { if (!await slots.WaitAsync(timeout, cancellationToken).ConfigureAwait(false)) throw new TimeoutException(); using var deadline = new CancellationTokenSource(timeout); bool release = true; Task<T>? work = null; state.Enter(); try { work = invoke(deadline.Token).AsTask(); return await work.WaitAsync(timeout, cancellationToken).ConfigureAwait(false); } catch when (work is { IsCompleted: false }) { release = false; state.Quarantine(); _ = ReleaseQuarantinedAsync(work, slots, state); throw; } finally { if (release) { state.Complete(); slots.Release(); } } }
    private static async Task ReleaseQuarantinedAsync<T>(Task<T> work, SemaphoreSlim slots, BaseSubjectRetirementOperationalState state) { try { _ = await work.ConfigureAwait(false); } catch { } finally { state.ReleaseQuarantine(); slots.Release(); } }
    public async ValueTask DisposeAsync() { long started = Stopwatch.GetTimestamp(); while (operationalState.Active + operationalState.Quarantined != 0 && Stopwatch.GetElapsedTime(started) < ShutdownDrainTimeout) await Task.Delay(10).ConfigureAwait(false); if (operationalState.Active + operationalState.Quarantined == 0) _providerSlots.Dispose(); }
    public void Dispose() { if (operationalState.Active + operationalState.Quarantined == 0) _providerSlots.Dispose(); }
    private static BaseSubjectRetirementBarrierKey Key(BaseSubjectRetirementBarrierRow row) => new() { ScopeKind = row.Scope.Kind, ScopeIndexDigest = row.Scope.IndexDigest.ToArray(), ContractId = row.Barrier.ContractId, ContractVersion = row.Barrier.ContractVersion, SubjectId = row.Barrier.SubjectId, AuthorityEpoch = row.Barrier.AuthorityEpoch, Incarnation = row.Barrier.Incarnation };
    private static int CompareKey(BaseSubjectRetirementBarrierKey left, BaseSubjectRetirementBarrierKey right) => KeyBytes(left).AsSpan().SequenceCompareTo(KeyBytes(right));
    private static byte[] KeyBytes(BaseSubjectRetirementBarrierKey key) => Encoding.UTF8.GetBytes($"{(int)key.ScopeKind:D2}\0{Convert.ToHexString(key.ScopeIndexDigest)}\0{key.ContractId}\0{key.ContractVersion:D10}\0{key.SubjectId.Value}\0{key.AuthorityEpoch.ToBase64Url()}\0{key.Incarnation.ToBase64Url()}");
    private static DateTimeOffset Min(DateTimeOffset left, DateTimeOffset right) => left <= right ? left : right;
    internal static DateTimeOffset RequiredEvidenceExpiry(DateTimeOffset issued, TimeSpan maximumCheckpointLag, DateTimeOffset barrierDeadline) =>
        Min(checked(issued + maximumCheckpointLag), Min(barrierDeadline, checked(issued.AddDays(30))));
    private static bool ProtectedScopeEquals(BaseProtectedSubjectScope left, BaseProtectedSubjectScope right) => left.Kind == right.Kind && CryptographicOperations.FixedTimeEquals(left.IndexDigest, right.IndexDigest) && CryptographicOperations.FixedTimeEquals(left.ProtectedCanonicalValue, right.ProtectedCanonicalValue);
    private static bool ValidChecksum(string value) => value.Length == 64 && value.All(static c => c is >= '0' and <= '9' or >= 'a' and <= 'f');
    private static bool CanonicalInputs(ImmutableArray<string> values) { if (values.IsDefault) return false; string? previous = null; foreach (string value in values) { if (string.IsNullOrEmpty(value) || previous is not null && string.CompareOrdinal(previous, value) >= 0) return false; previous = value; } return true; }
    private static long RetirementBarrierBytes(BaseSubjectRetirementBarrier barrier) => Encoding.UTF8.GetByteCount($"{barrier.ContractId}\0{barrier.ContractVersion}\0{barrier.SubjectId.Value}\0{barrier.AuthorityEpoch.ToBase64Url()}\0{barrier.Incarnation.ToBase64Url()}\0{barrier.TombstoneSequence}\0{barrier.RequiredConsumerSetChecksum}\0{barrier.CreatedAtUtc.UtcTicks}\0{barrier.DeadlineUtc.UtcTicks}\0{(int)barrier.State}\0{barrier.Generation}\0{barrier.BarrierChecksum}");
    private static BaseFailure<T> Failure<T>(OperationStatus status, string code, ErrorCategory category) => new(status, new BaseError { Code = code, Message = Message(code), Category = category }, null, null);
    private static string Message(string code) => code switch { BaseSubjectRetirementErrorCodes.ContractInvalid => "The subject retirement contract is invalid.", BaseSubjectRetirementErrorCodes.RegistrationConflict => "The subject retirement registration conflicts with the installed graph.", BaseSubjectRetirementErrorCodes.Unauthorized => "The subject retirement operation is not authorized.", BaseSubjectRetirementErrorCodes.ScopeAuthorityInvalid => "The subject retirement scope authority is invalid.", BaseSubjectRetirementErrorCodes.AcknowledgementConflict => "The subject retirement acknowledgement conflicts with current state.", BaseSubjectRetirementErrorCodes.SequenceInvalid => "The subject retirement sequence is invalid.", BaseSubjectRetirementErrorCodes.BarrierPending => "The subject retirement barrier is pending.", BaseSubjectRetirementErrorCodes.BarrierSatisfied => "The subject retirement barrier is already satisfied.", BaseSubjectRetirementErrorCodes.BarrierTimedOut => "The subject retirement barrier has timed out.", BaseSubjectRetirementErrorCodes.BarrierQuarantined => "The subject retirement barrier is quarantined.", BaseSubjectRetirementErrorCodes.OverrideConflict => "The subject retirement override conflicts with current state.", BaseSubjectRetirementErrorCodes.PurgeConflict => "The subject cannot be purged from its current retirement state.", BaseSubjectRetirementErrorCodes.RetentionPending => "The minimum subject retention period has not elapsed.", BaseSubjectRetirementErrorCodes.ConsumerRemovalPending => "Subject retirement consumer removal is still pending.", BaseSubjectRetirementErrorCodes.ProviderContractInvalid => "The provider cannot satisfy the subject retirement contract.", BaseSubjectRetirementErrorCodes.CapacityExceeded => "Subject retirement capacity is unavailable.", BaseSubjectRetirementErrorCodes.Timeout => "The subject retirement operation timed out.", BaseSubjectRetirementErrorCodes.CommitIndeterminate => "The subject retirement commit outcome is indeterminate.", BaseSubjectRetirementErrorCodes.MaintenanceRequired => "Subject retirement maintenance must complete before this operation.", _ => "The subject retirement operation failed." };
